CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL CHECK(role IN ('OPERATIONS_MANAGER','ADMIN','STAFF')),active BOOLEAN NOT NULL);
CREATE TABLE staff_members(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,user_id BIGINT UNIQUE REFERENCES users(id),name VARCHAR(120) NOT NULL,category VARCHAR(30) NOT NULL CHECK(category IN ('CHEF','KITCHEN_ASSISTANT','SUPERVISOR','SERVER')),contact VARCHAR(120),active BOOLEAN NOT NULL);
CREATE TABLE staff_availability(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,staff_id BIGINT NOT NULL REFERENCES staff_members(id),starts_at TIMESTAMP NOT NULL,ends_at TIMESTAMP NOT NULL CHECK(ends_at>starts_at),available BOOLEAN NOT NULL,notes VARCHAR(500));
CREATE TABLE scheduling_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,reference VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,event_date DATE NOT NULL,location VARCHAR(500) NOT NULL);
CREATE TABLE staff_schedules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,event_id BIGINT NOT NULL UNIQUE REFERENCES scheduling_events(id),status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','READY','PUBLISHED','CANCELLED')),published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE staff_requirements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,schedule_id BIGINT NOT NULL REFERENCES staff_schedules(id),area VARCHAR(20) NOT NULL CHECK(area IN ('KITCHEN','EVENT')),category VARCHAR(30) NOT NULL CHECK(category IN ('CHEF','KITCHEN_ASSISTANT','SUPERVISOR','SERVER')),required_count INTEGER NOT NULL CHECK(required_count BETWEEN 1 AND 100),starts_at TIMESTAMP NOT NULL,ends_at TIMESTAMP NOT NULL CHECK(ends_at>starts_at),notes VARCHAR(1000));
CREATE TABLE staff_assignments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,requirement_id BIGINT NOT NULL REFERENCES staff_requirements(id),staff_id BIGINT NOT NULL REFERENCES staff_members(id),UNIQUE(requirement_id,staff_id));
CREATE TABLE staffing_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,requirement_id BIGINT NOT NULL REFERENCES staff_requirements(id),number_needed INTEGER NOT NULL CHECK(number_needed>0),requested_at TIMESTAMP WITH TIME ZONE NOT NULL,status VARCHAR(30) NOT NULL CHECK(status IN ('OPEN','PARTIALLY_FULFILLED','FULFILLED','CANCELLED')),notes VARCHAR(1000));
CREATE TABLE staff_schedule_notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,assignment_id BIGINT NOT NULL UNIQUE REFERENCES staff_assignments(id),event_reference VARCHAR(40) NOT NULL,event_name VARCHAR(120) NOT NULL,staff_name VARCHAR(120) NOT NULL,area VARCHAR(20) NOT NULL,category VARCHAR(30) NOT NULL,starts_at TIMESTAMP NOT NULL,ends_at TIMESTAMP NOT NULL,published_at TIMESTAMP WITH TIME ZONE NOT NULL,sent_at TIMESTAMP WITH TIME ZONE,delivery_status VARCHAR(20) NOT NULL CHECK(delivery_status IN ('PENDING','SENT','DELIVERED','FAILED')),delivered_at TIMESTAMP WITH TIME ZONE,acknowledgment_status VARCHAR(20) NOT NULL CHECK(acknowledgment_status IN ('PENDING','ACKNOWLEDGED')),acknowledged_at TIMESTAMP WITH TIME ZONE,resend_count INTEGER NOT NULL CHECK(resend_count>=0),last_sent_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE schedule_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,schedule_id BIGINT NOT NULL REFERENCES staff_schedules(id),actor_id BIGINT NOT NULL REFERENCES users(id),action VARCHAR(60) NOT NULL,detail VARCHAR(1000) NOT NULL,occurred_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE schedule_lock(id INTEGER PRIMARY KEY);
INSERT INTO schedule_lock(id) VALUES(1);
CREATE INDEX assignment_staff ON staff_assignments(staff_id);
CREATE INDEX requirement_schedule ON staff_requirements(schedule_id);
CREATE INDEX availability_staff_interval ON staff_availability(staff_id,starts_at,ends_at);
CREATE INDEX notice_status ON staff_schedule_notifications(delivery_status,acknowledgment_status);

